package main

import (
	"bufio"
	"fmt"
	"strings"
)

func main() {
	input := strings.NewReader("alpha\nbeta\n")
	scanner := bufio.NewScanner(input)
	lineNumber := 1
	for scanner.Scan() {
		fmt.Printf("%d: %s\n", lineNumber, scanner.Text())
		lineNumber++
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
}
