package main

import (
	"bufio"
	"fmt"
	"strings"
)

func main() {
	longLine := strings.Repeat("x", 70*1024)
	scanner := bufio.NewScanner(strings.NewReader(longLine + "\n"))
	scanner.Buffer(make([]byte, 1024), 128*1024)

	if scanner.Scan() {
		fmt.Println("bytes in token:", len(scanner.Bytes()))
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
}
