package main

import (
	"bufio"
	"bytes"
	"fmt"
)

type countingWriter struct {
	bytes.Buffer
	calls int
}

func (w *countingWriter) Write(p []byte) (int, error) {
	w.calls++
	return w.Buffer.Write(p)
}

func main() {
	destination := &countingWriter{}
	writer := bufio.NewWriterSize(destination, 16)
	for _, part := range []string{"go", " is", " ready"} {
		if _, err := writer.WriteString(part); err != nil {
			panic(err)
		}
	}
	fmt.Println("before flush:", destination.calls)
	if err := writer.Flush(); err != nil {
		panic(err)
	}
	fmt.Println("after flush:", destination.calls, destination.String())
}
